const projPal=(p)=>{ if(!p) return ["#8B95A1","#F2F4F6"]; let h=0; for(const ch of String(p.id)) h=(h*31+ch.charCodeAt(0))>>>0; return PROJ_PAL[h%PROJ_PAL.length]; };
