    arr.sort((a,b)=>a.si-b.si||b.ei-a.ei||String(a.t.id).localeCompare(String(b.t.id)));
    const laneEnd=[];
    arr.forEach(b=>{ let lane=laneEnd.findIndex(end=>b.si>end); if(lane<0) lane=laneEnd.length; laneEnd[lane]=b.ei; b.lane=lane; });
    return arr;
